"""Original-incidence program for boundaries with any number of internal spans.

Only indices and ownership are compiled here. GN computes all curve samples,
corner contacts, arc geometry and heights from the live source Streets.
"""


def records(plan, compiled, cluster):
    source_sites={site.junction_id:(i,site) for i,site in enumerate(plan.sites)}
    ranges={jid:(first,count) for jid,first,count in compiled.junction_ranges}
    span_indices={span.identity:i for i,span in enumerate(plan.spans)}
    local={}; following={}; sites=[]; count=0
    for jid in cluster.physical_junction_ids:
        index,site=source_sites[jid]
        if ranges[jid][1]!=len(site.ports):raise ValueError('Original cluster port binding is stale')
        sites.append(dict(site=index,junction_id=jid,first=count,count=len(site.ports)))
        for at,port in enumerate(site.ports):
            if port.endpoint in local:raise ValueError('A source incidence has more than one physical owner')
            local[port.endpoint]=count+at
            following[port.endpoint]=site.ports[(at+1)%len(site.ports)].endpoint
        count+=len(site.ports)
    links=[];steps=[];footprints=set(cluster.footprint_spans);covered=set()
    for owner,link in enumerate(cluster.boundaries):
        corners=link.original_corners;crossed=link.traversed_spans
        if len(corners)!=len(crossed)+1 or not corners or corners[0]!=link.start_port:
            raise ValueError('Every boundary span must retain both original corner incidences')
        if link.end_port!=cluster.boundaries[(owner+1)%len(cluster.boundaries)].start_port:
            raise ValueError('Exterior boundary links must form one original cyclic walk')
        links.append(dict(a=local[link.start_port.endpoint],b=local[link.end_port.endpoint],
                          first=len(steps),count=len(corners)))
        for at,corner in enumerate(corners):
            row=dict(owner=owner,corner=local[corner.endpoint],span=-1,mid_a=0,mid_b=0,footprint=0)
            if at<len(crossed):
                identity,start=crossed[at];span=plan.spans[span_indices[identity]]
                if start not in (span.start.endpoint,span.end.endpoint):
                    raise ValueError('Boundary traversal must start at an original span endpoint')
                end=span.end.endpoint if start==span.start.endpoint else span.start.endpoint
                if following[corner.endpoint]!=start or corners[at+1].endpoint!=end:
                    raise ValueError('Boundary span does not connect its original physical corners')
                row.update(span=span_indices[identity],mid_a=local[start],mid_b=local[end],
                           footprint=int(identity in footprints))
                if identity in footprints:covered.add(identity)
            elif following[corner.endpoint]!=link.end_port.endpoint:
                raise ValueError('Last original corner does not reach the exterior approach')
            steps.append(row)
    if covered!=footprints:raise ValueError('An internal footprint is absent from the boundary program')
    return sites,links,steps


def tables(plan, compiled, cluster, label):
    from .curved_junction_bindings import _mesh
    groups=records(plan,compiled,cluster)
    def table(name,rows):
        return _mesh(label+' private '+name,[(0.,0.,0.)]*len(rows),[],[
            ('st_lq_'+key,'INT','POINT',[row[key] for row in rows]) for key in rows[0]])
    return {name:table(name,rows) for name,rows in zip(
        ('Chain Sites','Chain Links','Chain Steps'),groups)}
